163	                "INSERT INTO checkpoint (race_id, checkpoint_code, position, created_at) "
164	                        + "VALUES (?, ?, ?, ?)",
165	                rows,
166	                rows.size(),
167	                (ps, row) -> {
168	                    ps.setString(1, row.raceId());
169	                    ps.setString(2, row.checkpointCode());
