14	import com.example.starter.race.api.SubmitTimingRequest;
15	import com.example.starter.race.domain.EntryStatus;
16	import com.example.starter.race.domain.RaceStatus;
17	import com.example.starter.race.persistence.RaceRow;
18	import com.example.starter.race.support.AbstractRaceH2Test;
19	import com.example.starter.race.support.FixedClockTestConfig;
20	import org.junit.jupiter.api.Test;
21	import org.springframework.beans.factory.annotation.Autowired;
22	import org.springframework.boot.test.context.SpringBootTest;
23	import org.springframework.context.annotation.Import;
24	
25	import java.util.List;
26	
27	import static org.assertj.core.api.Assertions.assertThat;
28	import static org.assertj.core.api.Assertions.assertThatThrownBy;
29	
30	/**
31	 * 分段计时能力的 H2 数据库测试：乱序合法写入、相邻约束422、漏点排名、
32	 * 封榜固化分段明细与缺失项、封榜竞争、requestId 与 timingId 双重幂等。
33	 */
34	@SpringBootTest
35	@Import(FixedClockTestConfig.class)
36	class CheckpointServiceH2Test extends AbstractRaceH2Test {
37	
38	    private static final String RACE = "race-cp";
39	
40	    @Autowired
41	    private RaceService raceService;
42	
43	    @Autowired
44	    private com.fasterxml.jackson.databind.ObjectMapper objectMapper;
45	
46	    private String json(Object value) {
47	        try {
48	            return objectMapper.writeValueAsString(value);
49	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
50	            throw new IllegalStateException(ex);
51	        }
52	    }
53	
54	    private void createRace() {
55	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
56	    }
57	
58	    private void registerRunner(String bib, Long finishTimeMs, int expectedVersion, String reqId) {
59	        raceService.registerRunner(RACE,
60	                new RegisterRunnerRequest(bib, finishTimeMs, expectedVersion, reqId));
61	    }
62	
63	    private CheckpointsConfigResponse configure(int expectedVersion, String reqId,
64	                                                String... codeThenPosition) {
65	        java.util.List<ConfigureCheckpointsRequest.CheckpointDefinition> defs = new java.util.ArrayList<>();
66	        for (int i = 0; i < codeThenPosition.length; i += 2) {
67	            defs.add(new ConfigureCheckpointsRequest.CheckpointDefinition(
68	                    codeThenPosition[i], Integer.parseInt(codeThenPosition[i + 1])));
69	        }
70	        ServiceResult result = raceService.configureCheckpoints(RACE,
71	                new ConfigureCheckpointsRequest(defs, expectedVersion, reqId));
72	        assertThat(result.status()).isEqualTo(201);
73	        return (CheckpointsConfigResponse) result.body();
74	    }
75	
76	    private CheckpointTimingResponse submit(
77	            String bib, String timingId, String code, long elapsed,
78	            int expectedVersion, String reqId) {
79	        ServiceResult result = raceService.submitTiming(RACE, bib,
80	                new SubmitTimingRequest(timingId, code, elapsed, expectedVersion, reqId));
81	        assertThat(result.status()).isEqualTo(201);
82	        return (CheckpointTimingResponse) result.body();
83	    }
84	
85	    @Test
86	    void 配置检查点后版本加一且顺序返回不可再改() {
87	        createRace();
88	        // v2
89	        registerRunner("a", 10_000L, 1, "req-a");
90	        CheckpointsConfigResponse config = configure(2, "req-cfg", "cp1", "1", "cp3", "3", "cp2", "2");
91	
92	        assertThat(config.version()).isEqualTo(3);
93	        assertThat(config.checkpoints()).extracting(c -> c.position() + ":" + c.checkpointCode())
94	                .containsExactly("1:cp1", "2:cp2", "3:cp3");
95	
96	        // 重复配置 -> 409
97	        assertThatThrownBy(() -> configure(3, "req-cfg-again", "cp9", "1"))
98	                .isInstanceOf(ConflictException.class)
99	                .hasMessageContaining("不可修改");
100	        assertThat(raceService.getResults(RACE).version()).isEqualTo(3);
101	    }
102	
103	    @Test
104	    void 检查点配置参数校验失败分支() {
105	        createRace();
106	        // 空列表
107	        assertThatThrownBy(() -> raceService.configureCheckpoints(RACE,
108	                new ConfigureCheckpointsRequest(List.of(), 1, "req-empty")))
109	                .isInstanceOf(Exception.class);
110	        // position 不连续
111	        assertThatThrownBy(() -> raceService.configureCheckpoints(RACE,
112	                new ConfigureCheckpointsRequest(List.of(
113	                        new ConfigureCheckpointsRequest.CheckpointDefinition("a", 1),
114	                        new ConfigureCheckpointsRequest.CheckpointDefinition("b", 3)),
115	                        1, "req-gap")))
116	                .isInstanceOf(BadRequestException.class)
117	                .hasMessageContaining("连续");
118	        // 代码重复
119	        assertThatThrownBy(() -> raceService.configureCheckpoints(RACE,
120	                new ConfigureCheckpointsRequest(List.of(
121	                        new ConfigureCheckpointsRequest.CheckpointDefinition("dup", 1),
122	                        new ConfigureCheckpointsRequest.CheckpointDefinition("dup", 2)),
123	                        1, "req-dup")))
124	                .isInstanceOf(BadRequestException.class)
125	                .hasMessageContaining("重复");
126	        // 失败不推进版本
127	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(1);
128	    }
129	
130	    @Test
131	    void 乱序合法写入最终按顺序严格递增() {
132	        createRace();
133	        registerRunner("a", 10_000L, 1, "req-a");   // v2
134	        configure(2, "req-cfg", "c1", "1", "c2", "2", "c3", "3"); // v3
135	
136	        // 先提交 c3、再 c1、再 c2，乱序但每次都满足相邻约束
137	        submit("a", "t-3", "c3", 900L, 3, "req-t3");   // v4
138	        submit("a", "t-1", "c1", 100L, 4, "req-t1");   // v5
139	        submit("a", "t-2", "c2", 500L, 5, "req-t2");   // v6
140	
141	        RunnerTimingResponse timing = raceService.getRunnerTimings(RACE, "a");
142	        assertThat(timing.checkpoints()).extracting(CheckpointPassResponse::checkpointCode)
143	                .containsExactly("c1", "c2", "c3");
144	        assertThat(timing.checkpoints()).extracting(CheckpointPassResponse::elapsedMillis)
145	                .containsExactly(100L, 500L, 900L);
146	        assertThat(timing.version()).isEqualTo(6);
147	        // 只读查询不改版本
148	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(6);
149	    }
150	
151	    @Test
152	    void 违反相邻约束与完赛耗时约束返回422且不写入不推进版本() {
153	        createRace();
154	        registerRunner("a", 10_000L, 1, "req-a");
155	        configure(2, "req-cfg", "c1", "1", "c2", "2", "c3", "3");
156	
157	        submit("a", "t-3", "c3", 900L, 3, "req-t3"); // v4
158	
159	        // c2=950 不严格小于后序 c3=900 -> 422
160	        assertThatThrownBy(() -> submit("a", "t-2-bad", "c2", 950L, 4, "req-t2-bad"))
161	                .isInstanceOf(UnprocessableEntityException.class)
162	                .hasMessageContaining("后一检查点");
163	
164	        // c1=900 不严格小于后序 c3=900（相等）-> 422
165	        assertThatThrownBy(() -> submit("a", "t-1-bad", "c1", 900L, 4, "req-t1-eq"))
166	                .isInstanceOf(UnprocessableEntityException.class);
167	
168	        // 分段耗时必须小于完赛耗时：c2=10000 不小于 finish=10000 -> 422
169	        assertThatThrownBy(() -> submit("a", "t-2-finish", "c2", 10_000L, 4, "req-t2-fin"))
170	                .isInstanceOf(UnprocessableEntityException.class);
171	
172	        // 同一检查点重复 -> 422
173	        assertThatThrownBy(() -> submit("a", "t-3-again", "c3", 800L, 4, "req-t3-again"))
174	                .isInstanceOf(UnprocessableEntityException.class);
175	
176	        // 没有任何成功写入：仍只有 c3 一条，版本保持 4
177	        assertThat(raceService.getRunnerTimings(RACE, "a").checkpoints())
178	                .filteredOn(p -> p.elapsedMillis() != null).hasSize(1);
179	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(4);
180	
181	        // 合法的 c2 随后可成功（相邻：>无 c1 约束(空)，<c3=900）
182	        submit("a", "t-2", "c2", 500L, 4, "req-t2-ok");
183	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(5);
184	    }
185	
186	    @Test
187	    void 无完赛耗时选手提交分段返回422() {
188	        createRace();
189	        registerRunner("u", null, 1, "req-u"); // UNTIMED
190	        configure(2, "req-cfg", "c1", "1");
191	        assertThatThrownBy(() -> submit("u", "t-x", "c1", 100L, 3, "req-tx"))
192	                .isInstanceOf(UnprocessableEntityException.class)
193	                .hasMessageContaining("完赛耗时");
194	    }
195	
196	    @Test
197	    void 计时修订导致小于已有分段返回422() {
198	        createRace();
199	        registerRunner("a", 10_000L, 1, "req-a");
200	        configure(2, "req-cfg", "c1", "1");
201	        submit("a", "t-1", "c1", 5_000L, 3, "req-t1"); // v4
202	        // 把完赛耗时修订为 4000（小于分段 5000）-> 422
203	        assertThatThrownBy(() -> raceService.reviseTime(RACE,
204	                new com.example.starter.race.api.ReviseTimeRequest(
205	                        "a", 4_000L, 4, "req-rev-bad")))
206	                .isInstanceOf(UnprocessableEntityException.class);
207	        // 合法修订（仍严格大于 5000）成功
208	        raceService.reviseTime(RACE,
209	                new com.example.starter.race.api.ReviseTimeRequest(
210	                        "a", 6_000L, 4, "req-rev-ok"));
211	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(5);
212	    }
213	
214	    @Test
215	    void 漏点选手不参与排名全覆盖后恢复() {
216	        createRace();
217	        registerRunner("fast", 2_000L, 1, "req-fast");
218	        registerRunner("slow", 9_000L, 2, "req-slow"); // v3
219	        configure(3, "req-cfg", "c1", "1", "c2", "2"); // v4
220	
221	        // fast 两个检查点都漏；slow 全覆盖
222	        submit("slow", "s-1", "c1", 100L, 4, "req-s1"); // v5
223	        submit("slow", "s-2", "c2", 200L, 5, "req-s2"); // v6
224	
225	        StandingResponse standing = raceService.getResults(RACE);
226	        // fast 虽完赛耗时更短，但漏点不排名；slow 第1
227	        assertThat(standing.entries()).extracting(ResultEntryResponse::bib)
228	                .containsExactly("slow", "fast");
229	        assertThat(standing.entries().get(0).status()).isEqualTo(EntryStatus.RANKED);
230	        assertThat(standing.entries().get(0).rank()).isEqualTo(1);
231	        assertThat(standing.entries().get(1).status())
232	                .isEqualTo(EntryStatus.MISSING_CHECKPOINT);
233	        assertThat(standing.entries().get(1).missingCheckpoints()).containsExactly("c1", "c2");
234	        assertThat(standing.entries().get(1).checkpointCount()).isEqualTo(2);
235	
236	        // fast 补齐后恢复排名：fast(2000) 反超 slow(9000)
237	        submit("fast", "f-1", "c1", 100L, 6, "req-f1"); // v7
238	        StandingResponse stillMissing = raceService.getResults(RACE);
239	        assertThat(stillMissing.entries().get(1).status())
240	                .isEqualTo(EntryStatus.MISSING_CHECKPOINT);
241	        submit("fast", "f-2", "c2", 200L, 7, "req-f2"); // v8
242	        StandingResponse recovered = raceService.getResults(RACE);
243	        assertThat(recovered.entries()).extracting(ResultEntryResponse::bib)
244	                .containsExactly("fast", "slow");
245	        assertThat(recovered.entries()).extracting(ResultEntryResponse::status)
246	                .containsOnly(EntryStatus.RANKED);
247	        assertThat(recovered.entries()).extracting(ResultEntryResponse::rank)
248	                .containsExactly(1, 2);
249	    }
250	
251	    @Test
252	    void 缺失检查点汇总顺序稳定() {
253	        createRace();
254	        registerRunner("b", 9_000L, 1, "req-b");
255	        registerRunner("a", 8_000L, 2, "req-a"); // v3
256	        configure(3, "req-cfg", "c1", "1", "c2", "2"); // v4
257	        submit("a", "a-1", "c1", 100L, 4, "req-a1"); // v5
258	
259	        MissingCheckpointsResponse summary = raceService.getMissingCheckpoints(RACE);
260	        assertThat(summary.checkpointCount()).isEqualTo(2);
261	        assertThat(summary.runners()).extracting(r -> r.bib())
262	                .containsExactly("a", "b");
263	        assertThat(summary.runners().get(0).missingCheckpoints()).containsExactly("c2");
264	        assertThat(summary.runners().get(1).missingCheckpoints()).containsExactly("c1", "c2");
265	        // 只读不改版本
266	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(5);
267	    }
268	
269	    @Test
270	    void 封榜固化分段明细与缺失项且封榜后禁止新增分段() {
271	        createRace();
272	        registerRunner("a", 9_000L, 1, "req-a");
273	        registerRunner("b", 8_000L, 2, "req-b"); // v3
274	        configure(3, "req-cfg", "c1", "1", "c2", "2"); // v4
275	        submit("a", "a-1", "c1", 100L, 4, "req-a1"); // v5  a 漏 c2
276	
277	        ServiceResult sealed = raceService.sealRace(RACE,
278	                new SealRaceRequest(5, "req-seal")); // v6
279	        assertThat(sealed.status()).isEqualTo(200);
280	        StandingResponse standing = (StandingResponse) sealed.body();
281	        assertThat(standing.status()).isEqualTo(RaceStatus.SEALED);
282	
283	        // a 漏点不排名，b 无任何分段也漏点不排名
284	        assertThat(standing.entries()).extracting(ResultEntryResponse::status)
285	                .containsOnly(EntryStatus.MISSING_CHECKPOINT);
286	
287	        // 单选手分段查询走封榜快照：a 有 c1、缺 c2
288	        RunnerTimingResponse aTiming = raceService.getRunnerTimings(RACE, "a");
289	        assertThat(aTiming.checkpoints()).extracting(CheckpointPassResponse::checkpointCode)
290	                .containsExactly("c1", "c2");
291	        assertThat(aTiming.checkpoints().get(0).elapsedMillis()).isEqualTo(100L);
292	        assertThat(aTiming.checkpoints().get(0).timingId()).isEqualTo("a-1");
293	        assertThat(aTiming.checkpoints().get(1).elapsedMillis()).isNull();
294	        assertThat(aTiming.checkpoints().get(1).timingId()).isNull();
295	
296	        // b 两个检查点全部固化为缺失
297	        RunnerTimingResponse bTiming = raceService.getRunnerTimings(RACE, "b");
298	        assertThat(bTiming.checkpoints()).extracting(CheckpointPassResponse::elapsedMillis)
299	                .containsExactly(null, null);
300	
301	        // 缺失汇总走快照
302	        MissingCheckpointsResponse summary = raceService.getMissingCheckpoints(RACE);
303	        assertThat(summary.runners().get(0).bib()).isEqualTo("a");
304	        assertThat(summary.runners().get(0).missingCheckpoints()).containsExactly("c2");
305	        assertThat(summary.runners().get(1).missingCheckpoints()).containsExactly("c1", "c2");
306	
307	        // 封榜后新增分段 409
308	        assertThatThrownBy(() -> submit("a", "a-2", "c2", 200L, 6, "req-a2-late"))
309	                .isInstanceOf(ConflictException.class)
310	                .hasMessageContaining("封榜");
311	    }
312	
313	    @Test
314	    void 未配置检查点的赛事封榜与排名沿用旧规则() {
315	        createRace();
316	        registerRunner("a", 1_000L, 1, "req-a");
317	        registerRunner("b", 1_000L, 2, "req-b"); // v3
318	        ServiceResult sealed = raceService.sealRace(RACE, new SealRaceRequest(3, "req-seal"));
319	        StandingResponse standing = (StandingResponse) sealed.body();
320	        assertThat(standing.entries()).extracting(ResultEntryResponse::status)
321	                .containsOnly(EntryStatus.RANKED);
322	        assertThat(standing.entries()).extracting(ResultEntryResponse::rank)
323	                .containsExactly(1, 1);
324	        // 未配置检查点：单选手查询分段为空列表，不报错
325	        assertThat(raceService.getRunnerTimings(RACE, "a").checkpoints()).isEmpty();
326	        assertThat(raceService.getMissingCheckpoints(RACE).checkpointCount()).isZero();
327	    }
328	
329	    @Test
330	    void requestId同参重放原结果异参409且timingId双重幂等() {
331	        createRace();
332	        registerRunner("a", 10_000L, 1, "req-a");
333	        configure(2, "req-cfg", "c1", "1", "c2", "2");
334	
335	        SubmitTimingRequest req =
336	                new SubmitTimingRequest("t-same", "c1", 100L, 3, "req-submit");
337	        ServiceResult first = raceService.submitTiming(RACE, "a", req);
338	        ServiceResult replay = raceService.submitTiming(RACE, "a", req);
339	        assertThat(replay.status()).isEqualTo(first.status());
340	        // requestId 重放返回的是原响应体 JSON（JsonNode），按 JSON 文本比对
341	        assertThat(json(replay.body())).isEqualTo(json(first.body()));
342	        // 重放不重复推进版本（仍为 v4）
343	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(4);
344	
345	        // 同 requestId 异参 -> 409
346	        assertThatThrownBy(() -> raceService.submitTiming(RACE, "a",
347	                new SubmitTimingRequest("t-other", "c1", 200L, 3, "req-submit")))
348	                .isInstanceOf(ConflictException.class)
349	                .hasMessageContaining("requestId");
350	
351	        // 同 timingId 异参（即使换新 requestId）-> 409
352	        assertThatThrownBy(() -> raceService.submitTiming(RACE, "a",
353	                new SubmitTimingRequest("t-same", "c2", 200L, 4, "req-submit-other")))
354	                .isInstanceOf(ConflictException.class)
355	                .hasMessageContaining("timingId");
356	
357	        // 同 timingId 同参但新 requestId：作为分段重放返回原结果，不新增记录不推进版本
358	        ServiceResult timingReplay = raceService.submitTiming(RACE, "a",
359	                new SubmitTimingRequest("t-same", "c1", 100L, 999, "req-replay-timing"));
360	        assertThat(timingReplay.status()).isEqualTo(201);
361	        assertThat(((CheckpointTimingResponse) timingReplay.body()).elapsedMillis()).isEqualTo(100L);
362	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(4);
363	        assertThat(repository.findAllTimings(RACE)).hasSize(1);
364	    }
365	
366	    @Test
367	    void 业务失败不占用requestId键() {
368	        createRace();
369	        registerRunner("a", 10_000L, 1, "req-a");
370	        configure(2, "req-cfg", "c1", "1");
371	
372	        // 错误版本提交，业务失败回滚不占键
373	        assertThatThrownBy(() -> submit("a", "t-1", "c1", 100L, 999, "req-t1"))
374	                .isInstanceOf(ConflictException.class);
375	        assertThat(repository.findIdempotency("req-t1")).isEmpty();
376	        // 同 requestId 用正确版本重试成功
377	        ServiceResult retry = raceService.submitTiming(RACE, "a",
378	                new SubmitTimingRequest("t-1", "c1", 100L, 3, "req-t1"));
379	        assertThat(retry.status()).isEqualTo(201);
380	    }
381	
382	    @Test
383	    void 版本冲突串行化分段与封榜竞争() throws Exception {
384	        createRace();
385	        registerRunner("a", 10_000L, 1, "req-a");
