        orderedParams(
                "raceId", raceId,
                "expectedVersion", request.expectedVersion(),
                "checkpoints", definitions.stream()
                        .map(def -> def.position() + ":" + def.checkpointCode())
                        .toList()),
        () -> {
            RaceRow race = requireOpenRace(raceId, request.expectedVersion());
