                new ConfigureCheckpointsRequest.CheckpointDefinition("c1", 1, true),
                new ConfigureCheckpointsRequest.CheckpointDefinition("c2", 2, false))); // v3

        // 三源点走原单条计时入口 -> 422
        assertThatThrownBy(() -> raceService.submitTiming(RACE, "a",
